package practice;

import java.util.Map;

/** Stock in the bins of one warehouse. Every move between bins, and every stock count, goes through this class. */
public class Warehouse {

    /** One storage bin. Each bin is thread-safe on its own. */
    public interface Bin {
        int count();

        /** Removes qty units if the bin holds that many, and says whether it did. */
        boolean take(int qty);

        void add(int qty);
    }

    /** The bin used in production. */
    public static final class Shelf implements Bin {
        private int units;

        public Shelf(int units) {
            this.units = units;
        }

        @Override
        public synchronized int count() {
            return units;
        }

        @Override
        public synchronized boolean take(int qty) {
            if (units < qty) return false;
            units -= qty;
            return true;
        }

        @Override
        public synchronized void add(int qty) {
            units += qty;
        }
    }

    private final Map<String, Bin> bins;

    public Warehouse(Map<String, Bin> bins) {
        this.bins = Map.copyOf(bins);
    }

    public int count(String bin) {
        return bins.get(bin).count();
    }

    /** Moves qty units from one bin to another; moves nothing, and returns false, if the source holds fewer. */
    synchronized boolean move(String from, String to, int qty) {
        if (!bins.get(from).take(qty)) return false;
        bins.get(to).add(qty);
        return true;
    }

    /** The units in all bins together, for the hourly stock count. */
    synchronized int total() {
        int sum = 0;
        for (Bin bin : bins.values()) sum += bin.count();
        return sum;
    }
}

package practice;

import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            Warehouse w = new Warehouse(Map.of("P-02", new Warehouse.Shelf(40), "Q-08", new Warehouse.Shelf(5),
                    "R-19", new Warehouse.Shelf(12)));
            System.out.println("total before: " + w.total());
            System.out.println("move 15 P-02 -> Q-08: " + w.move("P-02", "Q-08", 15));
            System.out.println("move 30 R-19 -> P-02: " + w.move("R-19", "P-02", 30));
            System.out.println("P-02: " + w.count("P-02") + ", Q-08: " + w.count("Q-08") + ", R-19: " + w.count("R-19"));
            RuntimeException[] failed = {null};
            Thread mover = new Thread(() -> {
                try {
                    for (int i = 0; i < 2_000; i++) { w.move("Q-08", "R-19", 1); w.move("R-19", "Q-08", 1); }
                } catch (RuntimeException e) {
                    failed[0] = e;
                }
            });
            mover.start();
            int lowest = Integer.MAX_VALUE, highest = 0;
            do { int t = w.total(); lowest = Math.min(lowest, t); highest = Math.max(highest, t); } while (mover.isAlive());
            mover.join();
            if (failed[0] != null) throw failed[0];
            System.out.println("totals seen while moving: " + lowest + " to " + highest);
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

